    optional(
        :(foo(a, b=2, c=3, d, e=5; f=6) = nothing)
    ),
    [
        :(foo(a, b, c, d, e=5; f=6) = nothing),
        :(foo(a, b, d, e=5; f=6) = foo(a, b, 3, d, e; f=f)),
        :(foo(a, d, e=5; f=6) = foo(a, 2, 3, d, e; f=f)),
    ],
)

