    args = []
    for arg in ex.args
        if isa(arg, Expr)
            arg = strip_comments(arg)
        end

        if !isa(arg, LineNumberNode) && !isa(arg, String)
            push!(args, arg)
        end
    end

    return Expr(ex.head, args...)
