      wt = sqrt(denvec);
      Xnew = scale(wt, Xrot);
      ynew = wt .* yrot;
      b = Xnew \ ynew;
      r = y - BLAS.gemv('N', X, b);
      rnew = BLAS.gemv('T', UVfull, r);
