      loglOld = logl;
      logl = loglConst + sum(log, wt) -
        0.5 * BLAS.dot(length(evalVfull), rnew .^ 2, 1, denvec, 1);
      if abs(logl - loglOld) < tolX * (abs(logl) + 1.0)
        break
      end

